def iter_delimited_fields(record: str, *, delimiter: str = ",", trim: bool = True) -> Iterator[str]:
    if len(delimiter) != 1 or delimiter == '"' or delimiter.isspace():
        raise ValueError("The delimiter must be one non-whitespace character other than a quote")
    position = 0
    length = len(record)
    while True:
        if trim:
            while position < length and record[position].isspace():
                position += 1
        if position < length and record[position] == '"':
            position += 1
            characters = []
            while position < length:
                character = record[position]
                position += 1
                if character == '"':
                    if position < length and record[position] == '"':
                        characters.append('"')
                        position += 1
                        continue
                    break
                characters.append(character)
            else:
                raise ValueError("Unterminated quoted field")
            field = "".join(characters)
            if trim:
                while position < length and record[position].isspace():
                    position += 1
            if position < length and record[position] != delimiter:
                raise ValueError(f"Unexpected character after quoted field at offset {position}")
        else:
            end = record.find(delimiter, position)
            end = length if end < 0 else end
            field = record[position:end]
            if '"' in field:
                raise ValueError(f"Quote inside unquoted field at offset {position}")
            field, position = field.strip() if trim else field, end
        yield field
        if position == length:
            break
        position += 1

def monthly_loan_payment(self: "Loan", annual_rate: Decimal, months: int, principal: Decimal | None = None) -> Decimal:
    balance = self.principal if principal is None else principal
    if not balance.is_finite() or balance < 0:
        raise ValueError("Principal must be finite and nonnegative")
    if not annual_rate.is_finite() or annual_rate < 0:
        raise ValueError("Annual rate must be finite and nonnegative")
    if months <= 0:
        raise ValueError("Loan term must contain at least one month")
    monthly_rate = annual_rate / Decimal("12")
    if balance == 0:
        payment = Decimal("0")
    elif monthly_rate == 0:
        payment = balance / months
    else:
        growth = (Decimal("1") + monthly_rate) ** months
        payment = balance * monthly_rate * growth / (growth - Decimal("1"))
    return payment.quantize(self.currency_quantum, rounding=ROUND_HALF_UP)

def render_named_template(template: str, values: dict[str, str], strict: bool = True) -> str:
    pattern = r"\$\$|\$\{([A-Za-z_][A-Za-z0-9_]*)\}"
    pieces: list[str] = []
    position = 0
    for match in re.finditer(pattern, template):
        pieces.append(template[position:match.start()])
        name = match.group(1)
        if name is None:
            pieces.append("$")
        elif name in values:
            pieces.append(values[name])
        elif strict:
            raise KeyError(f"Missing template value: {name}")
        else:
            pieces.append(match.group(0))
        position = match.end()
    pieces.append(template[position:])
    return "".join(pieces)

async def inventory_directory(path: str | Path, *, suffixes: tuple[str, ...] = (), min_bytes: int = 0, include_hidden: bool = False) -> list[dict[str, str | int]]:
    if min_bytes < 0:
        raise ValueError("Minimum file size cannot be negative")
    if any(not suffix.startswith(".") for suffix in suffixes):
        raise ValueError("Each suffix must start with a dot")
    root = Path(path)
    root_metadata = await asyncio.to_thread(root.stat)
    if not stat.S_ISDIR(root_metadata.st_mode):
        raise NotADirectoryError(f"Inventory root is not a directory: {root}")
    allowed_suffixes = {suffix.casefold() for suffix in suffixes}
    entries = await asyncio.to_thread(sorted, root.rglob("*"))
    inventory = []
    for entry in entries:
        relative = entry.relative_to(root)
        if not include_hidden and any(part.startswith(".") for part in relative.parts):
            continue
        if allowed_suffixes and entry.suffix.casefold() not in allowed_suffixes:
            continue
        try:
            metadata = await asyncio.to_thread(entry.stat, follow_symlinks=False)
        except FileNotFoundError:
            continue
        if not stat.S_ISREG(metadata.st_mode):
            continue
        if metadata.st_size < min_bytes:
            continue
        inventory.append({"path": relative.as_posix(), "size": metadata.st_size, "modified_ns": metadata.st_mtime_ns})
    return inventory

def arithmetic_mean(self: object, values: list[float]) -> float:
    if not values:
        raise ValueError("Cannot compute the mean of an empty sample")
    numbers = [float(value) for value in values]
    if any(not math.isfinite(value) for value in numbers):
        raise ValueError("Sample values must be finite")
    return math.fsum(numbers) / len(numbers)

def sample_median(self: object, values: list[float]) -> float:
    if not values:
        raise ValueError("Cannot compute the median of an empty sample")
    numbers = sorted(float(value) for value in values)
    if any(not math.isfinite(value) for value in numbers):
        raise ValueError("Sample values must be finite")
    middle = len(numbers) // 2
    if len(numbers) % 2:
        return numbers[middle]
    return numbers[middle - 1] / 2.0 + numbers[middle] / 2.0

def trailing_moving_average(self: object, values: list[float], window: int, min_periods: int = 1) -> list[float | None]:
    if isinstance(window, bool) or not isinstance(window, int):
        raise TypeError("Window must be an integer")
    if isinstance(min_periods, bool) or not isinstance(min_periods, int):
        raise TypeError("Minimum periods must be an integer")
    if window < 1 or not 1 <= min_periods <= window:
        raise ValueError("Require window >= 1 and 1 <= min_periods <= window")
    numbers = [float(value) for value in values]
    if any(not math.isfinite(value) for value in numbers):
        raise ValueError("Sample values must be finite")
    averages: list[float | None] = []
    for end in range(1, len(numbers) + 1):
        start = max(0, end - window)
        count = end - start
        if count < min_periods:
            averages.append(None)
        else:
            averages.append(math.fsum(numbers[start:end]) / count)
    return averages

def iqr_outlier_indices(self: object, values: list[float], *, multiplier: float = 1.5, side: str = "both") -> list[int]:
    factor = float(multiplier)
    if not math.isfinite(factor) or factor < 0.0:
        raise ValueError("Multiplier must be finite and nonnegative")
    if side not in {"both", "lower", "upper"}:
        raise ValueError("Side must be 'both', 'lower', or 'upper'")
    numbers = [float(value) for value in values]
    if any(not math.isfinite(value) for value in numbers):
        raise ValueError("Sample values must be finite")
    if not numbers:
        return []
    ordered = sorted(numbers)
    quartiles: list[float] = []
    for proportion in (0.25, 0.75):
        position = proportion * (len(ordered) - 1)
        lower = math.floor(position)
        upper = math.ceil(position)
        fraction = position - lower
        if lower == upper:
            quartiles.append(ordered[lower])
        else:
            quartiles.append((1.0 - fraction) * ordered[lower] + fraction * ordered[upper])
    spread = quartiles[1] - quartiles[0]
    padding = 0.0 if factor == 0.0 else factor * spread
    lower_fence = quartiles[0] - padding
    upper_fence = quartiles[1] + padding
    indices: list[int] = []
    for index, value in enumerate(numbers):
        if side in {"both", "lower"} and value < lower_fence:
            indices.append(index)
        elif side in {"both", "upper"} and value > upper_fence:
            indices.append(index)
    return indices

