async def sample_median(observations: list[float]) -> float:
    if not observations:
        raise ValueError("Cannot calculate the median of an empty sample")
    ordered = sorted(observations)
    await asyncio.sleep(0)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return float(ordered[middle])
    return ordered[middle - 1] / 2.0 + ordered[middle] / 2.0

async def trailing_moving_average(values: list[float], window: int = 7, partial: bool = False) -> list[float]:
    if window < 1:
        raise ValueError("Window size must be positive")
    samples = list(values)
    if any(not math.isfinite(value) for value in samples):
        raise ValueError("Moving averages require finite observations")
    await asyncio.sleep(0)
    averages: list[float] = []
    active = deque()
    for index, value in enumerate(samples):
        active.append(value)
        if len(active) > window:
            active.popleft()
        if partial or len(active) == window:
            averages.append(math.fsum(active) / len(active))
        if (index + 1) % 512 == 0:
            await asyncio.sleep(0)
    return averages

async def interpolated_percentile(values: list[float], percentile: float = 50.0) -> float:
    if not math.isfinite(percentile) or not 0.0 <= percentile <= 100.0:
        raise ValueError("Percentile must be finite and between zero and one hundred")
    ordered = sorted(values)
    if not ordered:
        raise ValueError("Percentiles require at least one observation")
    if any(not math.isfinite(value) for value in ordered):
        raise ValueError("Percentiles require finite observations")
    await asyncio.sleep(0)
    position = (percentile / 100.0) * (len(ordered) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return float(ordered[lower])
    weight = position - lower
    return (1.0 - weight) * ordered[lower] + weight * ordered[upper]

def unique_labels(self: object, labels: list[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for label in labels:
        if label not in seen:
            seen.add(label)
            result.append(label)
    return result

def map_record_columns(self: object, records: list[dict[str, object]], mapping: dict[str, str], keep_unmapped: bool = True) -> list[dict[str, object]]:
    result: list[dict[str, object]] = []
    for record in records:
        renamed: dict[str, object] = {}
        for source, value in record.items():
            if source in mapping:
                destination = mapping[source]
            elif keep_unmapped:
                destination = source
            else:
                continue
            if destination in renamed:
                raise ValueError(f"Multiple columns map to {destination!r}")
            renamed[destination] = value
        result.append(renamed)
    return result

def consolidate_records(self: object, records: list[dict[str, object]], *, keys: tuple[str, ...], conflict: str = "error") -> list[dict[str, object]]:
    if not keys or len(set(keys)) != len(keys):
        raise ValueError("Keys must contain distinct column names")
    if conflict not in {"first", "last", "error"}:
        raise ValueError("Conflict policy must be first, last, or error")
    result: list[dict[str, object]] = []
    positions: dict[tuple[object, ...], int] = {}
    for record in records:
        if any(name not in record or record[name] is None for name in keys):
            raise ValueError("Every record must have non-null key values")
        identity = tuple(record[name] for name in keys)
        try:
            position = positions.get(identity)
        except TypeError as exc:
            raise TypeError("Record key values must be hashable") from exc
        if position is None:
            positions[identity] = len(result)
            result.append(record.copy())
            continue
        target = result[position]
        for column, value in record.items():
            if column not in target:
                target[column] = value
            elif column not in keys:
                previous = target[column]
                if previous is None:
                    target[column] = value
                elif value is None or value == previous:
                    continue
                elif conflict == "last":
                    target[column] = value
                elif conflict == "error":
                    raise ValueError(f"Conflicting values for column {column!r}")
    return result

def map_record_columns(records: Iterable[dict[str, object]], mapping: dict[str, str | None], preserve_unmapped: bool = True) -> Iterator[dict[str, object]]:
    for record in records:
        cleaned: dict[str, object] = {}
        for source, value in record.items():
            if source in mapping:
                destination = mapping[source]
                if destination is None:
                    continue
            elif preserve_unmapped:
                destination = source
            else:
                continue
            if destination in cleaned:
                raise ValueError(f"Multiple columns map to {destination!r}")
            cleaned[destination] = value
        yield cleaned

async def coerce_numeric_column(records: list[dict[str, object]], column: str, default: float | None = None, invalid: str = "raise") -> list[dict[str, object]]:
    if invalid not in {"raise", "coerce"}:
        raise ValueError("invalid must be 'raise' or 'coerce'")
    await asyncio.sleep(0)
    cleaned: list[dict[str, object]] = []
    for index, record in enumerate(records):
        row = record.copy()
        value = row.get(column)
        if value is None or isinstance(value, str) and not value.strip():
            row[column] = default
        else:
            try:
                number = float(value)
                if not math.isfinite(number):
                    raise ValueError("Numeric values must be finite")
                row[column] = number
            except (TypeError, ValueError, OverflowError):
                if invalid == "raise":
                    raise ValueError(f"Invalid numeric value in row {index}, column {column!r}") from None
                row[column] = default
        cleaned.append(row)
    return cleaned

def rate_limit_wait(self: "HttpClient", headers: dict[str, str], *, now: float | None = None, max_wait: float = 300.0) -> float:
    timestamp = time.time() if now is None else now
    if not math.isfinite(timestamp) or not math.isfinite(max_wait) or max_wait < 0:
        raise ValueError("Current time must be finite and maximum wait must be nonnegative")
    normalized = {name.casefold(): value.strip() for name, value in headers.items()}
    delay = 0.0
    retry_after = normalized.get("retry-after")
    if retry_after is not None:
        if re.fullmatch(r"[0-9]+", retry_after):
            delay = int(retry_after)
        else:
            try:
                retry_date = email.utils.parsedate_to_datetime(retry_after)
                if retry_date.tzinfo is None:
                    retry_date = retry_date.replace(tzinfo=datetime.timezone.utc)
                delay = max(0.0, retry_date.timestamp() - timestamp)
            except (ValueError, TypeError, OverflowError, OSError) as exc:
                raise ValueError("Retry-After must contain seconds or an HTTP date") from exc
    remaining = normalized.get("x-ratelimit-remaining")
    if remaining is not None:
        if not re.fullmatch(r"[0-9]+", remaining):
            raise ValueError("Rate-limit remaining must be a nonnegative integer")
        if int(remaining) == 0:
            reset = normalized.get("x-ratelimit-reset")
            if reset is not None:
                try:
                    reset_time = float(reset)
                except ValueError as exc:
                    raise ValueError("Rate-limit reset must be a Unix timestamp") from exc
                if not math.isfinite(reset_time) or reset_time < 0:
                    raise ValueError("Rate-limit reset must be finite and nonnegative")
                delay = max(delay, reset_time - timestamp)
    if delay > max_wait:
        raise TimeoutError("Required rate-limit wait exceeds the configured maximum")
    return float(delay)

async def clip_segment_to_box(start: tuple[float, float], end: tuple[float, float], bounds: tuple[float, float, float, float], *, include_touches: bool = True) -> tuple[tuple[float, float], tuple[float, float]] | None:
    if not all(math.isfinite(value) for value in (*start, *end, *bounds)):
        raise ValueError("Segment and bounding box coordinates must be finite")
    left, bottom, right, top = bounds
    if left > right or bottom > top:
        raise ValueError("Bounding box minimums must not exceed maximums")
    await asyncio.sleep(0)
    x, y = start
    dx, dy = end[0] - x, end[1] - y
    if not math.isfinite(dx) or not math.isfinite(dy):
        raise ValueError("Segment displacement exceeds the supported numeric range")
    if not include_touches and (left == right or bottom == top):
        return None
    if dx == 0 and dy == 0:
        if include_touches and left <= x <= right and bottom <= y <= top:
            return start, end
        return None
    enter, leave = 0.0, 1.0
    constraints = ((-dx, x - left), (dx, right - x), (-dy, y - bottom), (dy, top - y))
    for direction, distance in constraints:
        if direction == 0:
            if distance < 0 or (not include_touches and distance == 0):
                return None
            continue
        ratio = distance / direction
        if direction < 0:
            enter = max(enter, ratio)
        else:
            leave = min(leave, ratio)
        if enter > leave:
            return None
    if not include_touches and enter == leave:
        return None
    clipped_start = (x + enter * dx, y + enter * dy)
    clipped_end = (x + leave * dx, y + leave * dy)
    return clipped_start, clipped_end

def roll_dice(count: int, sides: int = 6) -> Iterator[int]:
    if count < 0:
        raise ValueError("Dice count must be nonnegative")
    if sides < 1:
        raise ValueError("A die must have at least one side")
    for _ in range(count):
        yield random.randint(1, sides)

async def roll_die(sides: int = 6, delay: float = 0.0) -> int:
    if sides < 2:
        raise ValueError("A die must have at least two sides")
    if delay < 0:
        raise ValueError("Roll delay cannot be negative")
    await asyncio.sleep(delay)
    return random.randint(1, sides)
